input.old_string:
private bool CheckIsLocked(bool isShowMsg = false)
{
    DateTime? dtmLockedToDate1 = null;
    DateTime? dtmLockedToDate2 = null;
    lblMsg.Text = "";

    bolIsLocked_Semester1 = SIM_Class_SemesterLock.IsLock(this.YearID, 1, this.ClassID, SIM_Class_SemesterLock.ETHIC, out dtmLockedToDate1);
    bolIsLocked_Semester2 = SIM_Class_SemesterLock.IsLock(this.YearID, 2, this.ClassID, SIM_Class_SemesterLock.ETHIC, out dtmLockedToDate2);

    if (bolIsLocked_Semester1 && bolIsLocked_Semester2)
        lblMsg.Text = " (Đã khóa cả 2 học kì)";
    else if(bolIsLocked_Semester2)
        lblMsg.Text = " (Đã khóa học kì 2)";
    else if (bolIsLocked_Semester1)
        lblMsg.Text = " (Đã khóa học kì 1)";

    if (isShowMsg && bolIsLocked_Semester1 && bolIsLocked_Semester2)
        MsgBox.ShowWarning(lblMsg.Text);

    if (dtmLockedToDate1 != null)
        lblMsg.Text = lblMsg.Text + " - " + "Ngày khóa kì 1: " + dtmLockedToDate1.Value.ToString("dd/MM/yyyy");

    if (dtmLockedToDate2 != null)
        lblMsg.Text = lblMsg.Text + " - " + "Ngày khóa kì 2: " + dtmLockedToDate2.Value.ToString("dd/MM/yyyy");

    return bolIsLocked_Semester1 && bolIsLocked_Semester2; // khóa 2 kì
}
